import { test, expect } from '@playwright/test';

test.describe('Table Row Context Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><table><thead><tr><th>Name</th><th>Email</th><th>Status</th></tr></thead><tbody><tr class="table-row" data-row-id="1"><td>John Doe</td><td>john@example.com</td><td>Active</td></tr><tr class="table-row" data-row-id="2"><td>Jane Smith</td><td>jane@example.com</td><td>Inactive</td></tr><tr class="table-row" data-row-id="3"><td>Bob Johnson</td><td>bob@example.com</td><td>Active</td></tr></tbody></table><div id="context-menu" style="display:none; position:absolute; background:white; border:1px solid #ccc; z-index:1000;"><div class="menu-item">Edit</div><div class="menu-item">Delete</div><div class="menu-item">View Details</div></div><script>document.querySelectorAll(".table-row").forEach(row => {row.addEventListener("contextmenu", (e) => {e.preventDefault();const menu = document.getElementById("context-menu");menu.style.display = "block";menu.style.left = e.pageX + "px";menu.style.top = e.pageY + "px";});});document.addEventListener("click", () => {document.getElementById("context-menu").style.display = "none";});</script></body></html>');
  });

  test('should display context menu when right-clicking on a table row', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();

    await firstRow.click({ button: 'right' });

    const contextMenu = page.locator('#context-menu');
    await expect(contextMenu).toBeVisible();
  });

  test('should show context menu with correct options', async ({ page }) => {
    const secondRow = page.locator('tbody tr').nth(1);

    await secondRow.click({ button: 'right' });

    const editOption = page.getByText('Edit');
    const deleteOption = page.getByText('Delete');
    const viewDetailsOption = page.getByText('View Details');

    await expect(editOption).toBeVisible();
    await expect(deleteOption).toBeVisible();
    await expect(viewDetailsOption).toBeVisible();
  });

  test('should hide context menu when clicking elsewhere', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();

    await firstRow.click({ button: 'right' });

    const contextMenu = page.locator('#context-menu');
    await expect(contextMenu).toBeVisible();

    await page.click('body', { position: { x: 100, y: 100 } });

    await expect(contextMenu).not.toBeVisible();
  });

  test('should position context menu at cursor location', async ({ page }) => {
    const thirdRow = page.locator('tbody tr').nth(2);

    const boundingBox = await thirdRow.boundingBox();
    const rightClickX = boundingBox!.x + boundingBox!.width / 2;
    const rightClickY = boundingBox!.y + boundingBox!.height / 2;

    await page.click('tbody tr:nth-child(3)', { 
      button: 'right',
      position: { x: boundingBox!.width / 2, y: boundingBox!.height / 2 }
    });

    const contextMenu = page.locator('#context-menu');
    await expect(contextMenu).toBeVisible();

    const menuStyle = await contextMenu.getAttribute('style');
    expect(menuStyle).toContain('display: block');
  });

  test('should work on different rows independently', async ({ page }) => {
    const firstRow = page.locator('tbody tr').first();
    const secondRow = page.locator('tbody tr').nth(1);

    await firstRow.click({ button: 'right' });
    const contextMenu = page.locator('#context-menu');
    await expect(contextMenu).toBeVisible();

    await page.click('body');
    await expect(contextMenu).not.toBeVisible();

    await secondRow.click({ button: 'right' });
    await expect(contextMenu).toBeVisible();
  });
});
